    start.onclick=async()=>{try{await loadModels();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});video.srcObject=stream;video.style.display='block';await video.play();start.disabled=true;stop.disabled=false;setMsg('Camera ready. Enroll first, or verify your enrolled face.');refresh()}catch(e){setMsg(e.message||'Could not start camera. Allow camera access and use localhost/HTTPS.',true);notify('Camera/model setup failed','error')}};
    stop.onclick=()=>{if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;video.style.display='none';start.disabled=false;stop.disabled=true;enroll.disabled=true;verify.disabled=true;setMsg('Camera stopped.');};
